def get_dependency_scope(
    self,
    dependency: Dependency,
    scope: str | None = None,
    scope_default: str | None = None,
) -> str:
    """
    Get the scope of a dependency.
    """
    if scope is not None:
        return scope
    if scope_default is not None:
        return scope_default
    return self.get_default_scope(dependency)

